using BanHangTraSua.Helpers;using BanHangTraSua.Models;using Microsoft.Extensions.Configuration;using Microsoft.EntityFrameworkCore;using Serilog;using System.Net.Http;using System.Globalization;using System.Drawing;
namespace BanHangTraSua;
public class MainForm:Form{readonly AppConfig cfg;readonly TabControl tabs=new(){Dock=DockStyle.Fill};readonly DataGridView menuGrid=Grid(),billGrid=Grid(),detailGrid=Grid();readonly TextBox ten=new(){Width=160},search=new(){Width=150};readonly NumericUpDown gia=new(){Maximum=1000000000,Increment=1000,ThousandsSeparator=true};readonly CheckBox dangban=new(){Text="Đang bán",Checked=true};readonly ComboBox dm=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=160},dmBan=new(){DropDownStyle=ComboBoxStyle.DropDownList,Width=160};readonly ListBox monList=new(){Width=250,Height=300};readonly NumericUpDown soLy=new(){Minimum=1,Maximum=100,Value=1};readonly Label total=new(){AutoSize=true,Font=new Font("Segoe UI",14,FontStyle.Bold)},payInfo=new(){AutoSize=true};readonly PictureBox qr=new(){Width=260,Height=260,SizeMode=PictureBoxSizeMode.Zoom,BorderStyle=BorderStyle.FixedSingle};readonly DateTimePicker ngayLoc=new(){Format=DateTimePickerFormat.Short};int menuId=0;readonly Dictionary<int,(MonUong Mon,int Qty)> cart=new();static readonly HttpClient http=new(){Timeout=TimeSpan.FromSeconds(12)};
 public MainForm(IConfiguration c){cfg=AppConfig.Load(c);Text=cfg.Payment.ShopName+" - Bán hàng quán trà sữa v1.0.0";Width=1200;Height=800;StartPosition=FormStartPosition.CenterScreen;tabs.TabPages.Add(BuildMenu());tabs.TabPages.Add(BuildSales());tabs.TabPages.Add(BuildBills());Controls.Add(tabs);LoadCategories();LoadMenu();LoadBills();}
 static DataGridView Grid()=>new(){Dock=DockStyle.Fill,ReadOnly=true,AutoGenerateColumns=true,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};QLTraSuaContext Db()=>cfg.Db();TabPage BuildMenu(){var p=new TabPage("Thực đơn");var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=110};top.Controls.AddRange(new Control[]{new Label{Text="Tên món"},ten,new Label{Text="Danh mục"},dm,new Label{Text="Giá"},gia,dangban});foreach(var (s,a) in new (string,Action)[]{("Thêm",AddMenu),("Sửa",EditMenu),("Xóa",DeleteMenu),("Làm mới",LoadMenu)}){var b=new Button{Text=s,AutoSize=true};b.Click+=(_,_)=>a();top.Controls.Add(b);}top.Controls.Add(new Label{Text="Tìm tên"});top.Controls.Add(search);var f=new Button{Text="Tìm"};f.Click+=(_,_)=>LoadMenu();top.Controls.Add(f);var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,SplitterDistance=95};split.Panel1.Controls.Add(top);split.Panel2.Controls.Add(menuGrid);p.Controls.Add(split);menuGrid.SelectionChanged+=(_,_)=>PickMenu();return p;}
 TabPage BuildSales(){var p=new TabPage("Bán hàng");var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=80};top.Controls.Add(new Label{Text="Danh mục"});top.Controls.Add(dmBan);dmBan.SelectedIndexChanged+=(_,_)=>LoadSellingItems();top.Controls.Add(new Label{Text="Số ly"});top.Controls.Add(soLy);var add=new Button{Text="Thêm vào đơn"};add.Click+=(_,_)=>AddCart();top.Controls.Add(add);var del=new Button{Text="Xóa dòng"};del.Click+=(_,_)=>RemoveCart();top.Controls.Add(del);var pay=new Button{Text="Thanh toán chuyển khoản"};pay.Click+=async(_,_)=>await CreateQr();top.Controls.Add(pay);var received=new Button{Text="Đã nhận tiền"};received.Click+=(_,_)=>SaveBill("Chuyển khoản",true);top.Controls.Add(received);var cash=new Button{Text="Tiền mặt"};cash.Click+=(_,_)=>SaveBill("Tiền mặt",true);top.Controls.Add(cash);var split=new SplitContainer{Dock=DockStyle.Fill,SplitterDistance=280};split.Panel1.Controls.Add(monList);split.Panel2.Controls.Add(billGrid);var bottom=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=320};bottom.Controls.Add(total);bottom.Controls.Add(qr);bottom.Controls.Add(payInfo);p.Controls.Add(split);p.Controls.Add(bottom);p.Controls.Add(top);return p;}
 TabPage BuildBills(){var p=new TabPage("Hóa đơn");var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=40};top.Controls.Add(new Label{Text="Ngày"});top.Controls.Add(ngayLoc);var b=new Button{Text="Lọc"};b.Click+=(_,_)=>LoadBills();top.Controls.Add(b);var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal};split.Panel1.Controls.Add(billListGrid);split.Panel2.Controls.Add(detailGrid);billListGrid.SelectionChanged+=(_,_)=>LoadDetails();p.Controls.Add(split);p.Controls.Add(top);return p;}readonly DataGridView billListGrid=Grid();
 void LoadCategories(){try{using var db=Db();var list=db.DanhMucMon.AsNoTracking().OrderBy(x=>x.TenDM).ToList();dm.DataSource=list.ToList();dm.DisplayMember="TenDM";dm.ValueMember="MaDM";dmBan.DataSource=list;dmBan.DisplayMember="TenDM";dmBan.ValueMember="MaDM";}catch(Exception ex){Log.Error(ex,"Load categories");MessageBox.Show("Không kết nối được CSDL. Hãy chạy script SQL và kiểm tra appsettings.json.");}}
 void LoadMenu(){try{using var db=Db();var q=db.MonUong.AsNoTracking().Include(x=>x.DanhMucMon).AsQueryable();if(!string.IsNullOrWhiteSpace(search.Text))q=q.Where(x=>x.TenMon.Contains(search.Text));if(dm.SelectedValue is int id)q=q.Where(x=>x.MaDM==id);menuGrid.DataSource=q.Select(x=>new{ x.MaMon,x.TenMon,x.GiaBan,x.DangBan,x.MaDM,TenDanhMuc=x.DanhMucMon!.TenDM}).ToList();}catch(Exception ex){Log.Error(ex,"Load menu");MessageBox.Show("Không tải được thực đơn.");}}
 void PickMenu(){if(menuGrid.CurrentRow==null)return;try{menuId=Convert.ToInt32(menuGrid.CurrentRow.Cells["MaMon"].Value);ten.Text=Convert.ToString(menuGrid.CurrentRow.Cells["TenMon"].Value)??"";gia.Value=Convert.ToDecimal(menuGrid.CurrentRow.Cells["GiaBan"].Value);dangban.Checked=Convert.ToBoolean(menuGrid.CurrentRow.Cells["DangBan"].Value);dm.SelectedValue=Convert.ToInt32(menuGrid.CurrentRow.Cells["MaDM"].Value);}catch{}}
 void AddMenu(){if(string.IsNullOrWhiteSpace(ten.Text)||dm.SelectedValue==null){MessageBox.Show("Nhập tên món và chọn danh mục.");return;}try{using var db=Db();db.MonUong.Add(new(){TenMon=ten.Text.Trim(),GiaBan=gia.Value,DangBan=dangban.Checked,MaDM=(int)dm.SelectedValue});db.SaveChanges();LoadMenu();Log.Information("Added menu item");}catch(Exception ex){Log.Error(ex,"Add menu");MessageBox.Show("Không thêm được món.");}}
 void EditMenu(){if(menuId==0)return;try{using var db=Db();var x=db.MonUong.Find(menuId);if(x==null)return;x.TenMon=ten.Text.Trim();x.GiaBan=gia.Value;x.DangBan=dangban.Checked;x.MaDM=(int)dm.SelectedValue!;db.SaveChanges();LoadMenu();Log.Information("Updated menu item {Id}",menuId);}catch(Exception ex){Log.Error(ex,"Edit menu");MessageBox.Show("Không sửa được món.");}}
 void DeleteMenu(){if(menuId==0)return;if(MessageBox.Show("Xóa món này?","Xác nhận",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;try{using var db=Db();var x=db.MonUong.Find(menuId);if(x!=null)db.Remove(x);db.SaveChanges();LoadMenu();}catch(Exception ex){Log.Error(ex,"Delete menu");MessageBox.Show("Không xóa được món có trong hóa đơn.");}}
 void LoadSellingItems(){try{using var db=Db();if(dmBan.SelectedValue is int id)monList.DataSource=db.MonUong.AsNoTracking().Where(x=>x.MaDM==id&&x.DangBan).OrderBy(x=>x.TenMon).Select(x=>new ItemDisplay(x.MaMon,x.TenMon,x.GiaBan)).ToList();monList.DisplayMember="Text";}catch(Exception ex){Log.Error(ex,"Load selling items");}}record ItemDisplay(int Id,string Name,decimal Price){public string Text=>$"{Name} - {Price:N0} đ";}
 void AddCart(){if(monList.SelectedItem is not ItemDisplay m)return;using var db=Db();var full=db.MonUong.Find(m.Id);if(full==null)return;if(cart.ContainsKey(m.Id)){var old=cart[m.Id];cart[m.Id]=(old.Mon,old.Qty+(int)soLy.Value);}else cart[m.Id]=(full,(int)soLy.Value);RenderCart();}void RemoveCart(){if(billGrid.CurrentRow==null)return;try{int id=Convert.ToInt32(billGrid.CurrentRow.Cells["MaMon"].Value);cart.Remove(id);RenderCart();}catch{}}void RenderCart(){billGrid.DataSource=cart.Select(k=>new{MaMon=k.Key,TenMon=k.Value.Mon.TenMon,SoLy=k.Value.Qty,DonGia=k.Value.Mon.GiaBan,ThanhTien=k.Value.Mon.GiaBan*k.Value.Qty}).ToList();decimal sum=cart.Sum(x=>x.Value.Mon.GiaBan*x.Value.Qty);total.Text=$"Tổng tiền: {sum:N0} đ";payInfo.Text="";}
 decimal CartTotal()=>cart.Sum(x=>x.Value.Mon.GiaBan*x.Value.Qty);string Info(int hd,decimal amount)=>$"TRASUA HD{hd}";async Task CreateQr(){if(cart.Count==0){MessageBox.Show("Giỏ hàng đang trống.");return;}decimal amount=CartTotal();string info="TRASUA HD"+DateTime.Now.ToString("yyyyMMddHHmmss");string url=$"https://img.vietqr.io/image/{Uri.EscapeDataString(cfg.Payment.BankId)}-{Uri.EscapeDataString(cfg.Payment.AccountNo)}-{Uri.EscapeDataString(cfg.Payment.Template)}.png?amount={amount:0}&addInfo={Uri.EscapeDataString(info)}&accountName={Uri.EscapeDataString(cfg.Payment.AccountName)}";payInfo.Text=$"Ngân hàng: {cfg.Payment.BankId}
Số tài khoản: {cfg.Payment.AccountNo}
Tên tài khoản: {cfg.Payment.AccountName}
Số tiền: {amount:N0} đ
Nội dung: {info}";try{var bytes=await http.GetByteArrayAsync(url);using var ms=new MemoryStream(bytes);using var img=Image.FromStream(ms);qr.Image=new Bitmap(img);Log.Information("QR created for amount {Amount}; account masked",amount);}catch(Exception ex){Log.Error(ex,"QR image download failed");MessageBox.Show("Không tải được QR do lỗi mạng. Vẫn có thể dùng thông tin chuyển khoản dạng chữ hoặc chọn Tiền mặt.

"+payInfo.Text);}}
 void SaveBill(string method,bool paid){if(cart.Count==0){MessageBox.Show("Giỏ hàng đang trống.");return;}using var db=Db();using var tx=db.Database.BeginTransaction();try{var h=new HoaDon{NgayLap=DateTime.Now,TongTien=CartTotal(),HinhThucTT=method,DaThanhToan=paid};db.HoaDon.Add(h);db.SaveChanges();foreach(var item in cart.Values)db.ChiTietHoaDon.Add(new(){MaHD=h.MaHD,MaMon=item.Mon.MaMon,SoLy=item.Qty,DonGia=item.Mon.GiaBan});db.SaveChanges();tx.Commit();Log.Information("Bill saved {Id}, amount {Amount}, method {Method}",h.MaHD,h.TongTien,method);cart.Clear();qr.Image=null;RenderCart();LoadBills();MessageBox.Show($"Đã lưu hóa đơn HD{h.MaHD}.");}catch(Exception ex){tx.Rollback();Log.Error(ex,"Save bill failed");MessageBox.Show("Không thể lưu hóa đơn.");}}
 void LoadBills(){try{using var db=Db();var day=ngayLoc.Value.Date;billListGrid.DataSource=db.HoaDon.AsNoTracking().Where(x=>x.NgayLap>=day&&x.NgayLap<day.AddDays(1)).OrderByDescending(x=>x.NgayLap).Select(x=>new{x.MaHD,x.NgayLap,x.HinhThucTT,x.TongTien,x.DaThanhToan}).ToList();}catch(Exception ex){Log.Error(ex,"Load bills");}}void LoadDetails(){if(billListGrid.CurrentRow==null)return;try{int id=Convert.ToInt32(billListGrid.CurrentRow.Cells["MaHD"].Value);using var db=Db();detailGrid.DataSource=db.ChiTietHoaDon.AsNoTracking().Where(x=>x.MaHD==id).Include(x=>x.MonUong).Select(x=>new{x.MaHD,x.MaMon,TenMon=x.MonUong!.TenMon,x.SoLy,x.DonGia,ThanhTien=x.SoLy*x.DonGia}).ToList();}catch(Exception ex){Log.Error(ex,"Load bill details");}}
}